/**
 * Inline the built snippet JS into the edge worker bundle.
 *
 * Reads packages/snippet/dist/snippet.js → writes
 * packages/edge/src/snippet-asset.ts exporting SNIPPET_JS (string),
 * SNIPPET_ETAG (quoted hex prefix), and SNIPPET_BYTES (raw length).
 *
 * Run via: pnpm build:snippet:inline (also runs the snippet build first).
 *
 * Why inline instead of fetching from a separate origin: the edge worker
 * is already the source of truth for visitor-facing requests. Same origin
 * = one fewer DNS lookup per page load, atomic snippet+worker updates.
 *
 * The generated file IS committed so local wrangler dev + CI tests work
 * without needing to run this script first. Re-run whenever the snippet
 * source changes — the pre-deploy hook does this automatically.
 */

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { brotliCompressSync, gzipSync, constants as zlibConstants } from "node:zlib";

const REPO_ROOT = resolve(import.meta.dirname, "..");
const SNIPPET_PATH = resolve(REPO_ROOT, "packages/snippet/dist/snippet.js");
const OUTPUT_PATH = resolve(REPO_ROOT, "packages/edge/src/snippet-asset.ts");
const PICKER_PATH = resolve(REPO_ROOT, "packages/snippet/dist/picker.js");
const PICKER_OUTPUT_PATH = resolve(REPO_ROOT, "packages/edge/src/picker-asset.ts");
const RICH_PATH = resolve(REPO_ROOT, "packages/snippet/dist/rich.js");
const RICH_OUTPUT_PATH = resolve(REPO_ROOT, "packages/edge/src/rich-asset.ts");

const content = readFileSync(SNIPPET_PATH, "utf8");
const hash = createHash("sha256").update(content).digest("hex").substring(0, 16);
const etag = `"${hash}"`;

const out = `// Auto-generated by scripts/inline-snippet-to-edge.ts. DO NOT EDIT.
// Re-run via: pnpm build:snippet:inline

export const SNIPPET_JS = ${JSON.stringify(content)};
export const SNIPPET_ETAG = ${JSON.stringify(etag)};
export const SNIPPET_BYTES = ${content.length};
`;

writeFileSync(OUTPUT_PATH, out);

console.log(`inlined ${content.length} bytes → packages/edge/src/snippet-asset.ts (etag ${etag})`);

// The picker module (pick mode only) rides the same way, served at /picker.js.
const picker = readFileSync(PICKER_PATH, "utf8");
const pickerHash = createHash("sha256").update(picker).digest("hex").substring(0, 16);
const pickerEtag = `"${pickerHash}"`;
writeFileSync(
  PICKER_OUTPUT_PATH,
  `// Auto-generated by scripts/inline-snippet-to-edge.ts. DO NOT EDIT.
// Re-run via: pnpm build:snippet:inline

export const PICKER_JS = ${JSON.stringify(picker)};
export const PICKER_ETAG = ${JSON.stringify(pickerEtag)};
export const PICKER_BYTES = ${picker.length};
`,
);
console.log(
  `inlined ${picker.length} bytes → packages/edge/src/picker-asset.ts (etag ${pickerEtag})`,
);

// The rich writers (2026-09-30), served at /rich.js. The etag is the same
// 16-hex hash build.ts stamps into the snippet as the `?v=` of its URL
// (buildRich, contentHash), so the edge can cache a matching request for a
// year: a new build is a new URL.
const rich = readFileSync(RICH_PATH, "utf8");
const richHash = createHash("sha256").update(rich).digest("hex").substring(0, 16);
const richEtag = `"${richHash}"`;
if (!content.includes(richHash)) {
  throw new Error(
    `dist/snippet.js does not carry rich.js's version ${richHash}: rebuild the snippet (pnpm --filter @rawuser/snippet build) before inlining`,
  );
}
writeFileSync(
  RICH_OUTPUT_PATH,
  `// Auto-generated by scripts/inline-snippet-to-edge.ts. DO NOT EDIT.
// Re-run via: pnpm build:snippet:inline

export const RICH_JS = ${JSON.stringify(rich)};
export const RICH_ETAG = ${JSON.stringify(richEtag)};
export const RICH_BYTES = ${rich.length};
`,
);
console.log(`inlined ${rich.length} bytes → packages/edge/src/rich-asset.ts (etag ${richEtag})`);

// ---------------------------------------------------------------------------
// The boot and the core (docs/specs/faster-tag.md step 4, 2026-10-25).
//
// dist/snippet.js above is also the shared core, served at
// /s/_core/{hash}.js with the same 16-hex hash as its etag. dist/boot.js is
// what a customer's /s/{id}.js runs for the normal policy; it names the core
// build it was made with, so it must carry this build's hash.
//
// A browser keeps a boot a day and five minutes, so a boot from before a
// deploy must still find its own core: core-assets.ts keeps the current
// build and the builds it replaced, for CORE_KEEP_DAYS and at most
// CORE_KEEP_MAX of them, each precompressed (brotli 11 and gzip 9, the
// bytes the edge sends as they are). An address the edge no longer keeps
// gets the current core, briefly cached; the core checks the boot's handoff
// version before it takes anything over.
// ---------------------------------------------------------------------------

const BOOT_PATH = resolve(REPO_ROOT, "packages/snippet/dist/boot.js");
const BOOT_OUTPUT_PATH = resolve(REPO_ROOT, "packages/edge/src/boot-asset.ts");
const CORES_OUTPUT_PATH = resolve(REPO_ROOT, "packages/edge/src/core-assets.ts");
const CORE_KEEP_DAYS = 7;
const CORE_KEEP_MAX = 8;

const boot = readFileSync(BOOT_PATH, "utf8");
const bootHash = createHash("sha256").update(boot).digest("hex").substring(0, 16);
if (!boot.includes(`"${hash}"`)) {
  throw new Error(
    `dist/boot.js does not carry the core's hash ${hash}: rebuild the snippet (pnpm --filter @rawuser/snippet build) before inlining`,
  );
}
if (!boot.includes(richHash)) {
  throw new Error(`dist/boot.js does not carry rich.js's version ${richHash}: rebuild the snippet`);
}
writeFileSync(
  BOOT_OUTPUT_PATH,
  `// Auto-generated by scripts/inline-snippet-to-edge.ts. DO NOT EDIT.
// Re-run via: pnpm build:snippet:inline

export const BOOT_JS = ${JSON.stringify(boot)};
export const BOOT_ETAG = ${JSON.stringify(`"${bootHash}"`)};
/** The core build this boot loads, /s/_core/{BOOT_CORE}.js. */
export const BOOT_CORE = ${JSON.stringify(hash)};
export const BOOT_BYTES = ${boot.length};
`,
);
console.log(
  `inlined ${boot.length} bytes → packages/edge/src/boot-asset.ts (etag "${bootHash}", core ${hash})`,
);

interface CoreBuild {
  /** The 16-hex hash, the address and the etag. */
  h: string;
  /** When a later build replaced it (ISO), absent for the current one. */
  retired?: string;
  /** Brotli quality 11 and gzip level 9, base64. */
  br: string;
  gz: string;
}

const BUILDS_START = "export const CORE_BUILDS: CoreBuild[] = ";
let kept: CoreBuild[] = [];
try {
  const prev = readFileSync(CORES_OUTPUT_PATH, "utf8");
  const at = prev.indexOf(BUILDS_START);
  if (at === -1)
    throw new Error("core-assets.ts has no CORE_BUILDS line: refusing to drop its builds");
  const line = prev.slice(at + BUILDS_START.length, prev.indexOf(";\n", at));
  kept = JSON.parse(line) as CoreBuild[];
} catch (e) {
  if ((e as NodeJS.ErrnoException).code !== "ENOENT") throw e;
}
const now = new Date();
const current = kept.find((b) => b.h === hash);
const builds: CoreBuild[] = current
  ? // The same build again: nothing retires.
    kept
  : [
      {
        h: hash,
        br: brotliCompressSync(content, {
          params: {
            [zlibConstants.BROTLI_PARAM_QUALITY]: 11,
            [zlibConstants.BROTLI_PARAM_MODE]: zlibConstants.BROTLI_MODE_TEXT,
          },
        }).toString("base64"),
        gz: gzipSync(content, { level: 9 }).toString("base64"),
      },
      ...kept.map((b) => (b.retired ? b : { ...b, retired: now.toISOString() })),
    ];
const cutoff = now.getTime() - CORE_KEEP_DAYS * 86_400_000;
const current0 = builds.filter((b) => !b.retired);
if (current0.length !== 1 || current0[0]?.h !== hash) {
  throw new Error(`core-assets.ts would not have exactly one current build ${hash}`);
}
const previous = builds
  .filter((b) => b.retired && Date.parse(b.retired) >= cutoff)
  .sort((a, b) => Date.parse(b.retired ?? "") - Date.parse(a.retired ?? ""))
  .slice(0, CORE_KEEP_MAX);
const all = [...current0, ...previous];
writeFileSync(
  CORES_OUTPUT_PATH,
  `// Auto-generated by scripts/inline-snippet-to-edge.ts. DO NOT EDIT.
// Re-run via: pnpm build:snippet:inline
//
// The shared core's builds (docs/specs/faster-tag.md step 4): the current
// one (its text is SNIPPET_JS in snippet-asset.ts) and the ones it replaced
// in the last ${CORE_KEEP_DAYS} days (at most ${CORE_KEEP_MAX}), precompressed. A
// browser's boot from before a deploy still finds its own core here.

export interface CoreBuild {
  h: string;
  retired?: string;
  br: string;
  gz: string;
}

${BUILDS_START}${JSON.stringify(all)};
`,
);
console.log(
  `kept ${all.length} core build(s) → packages/edge/src/core-assets.ts (current ${hash}${previous.length ? `, previous ${previous.map((b) => b.h).join(", ")}` : ""})`,
);
